import psycopg2
from psycopg2 import sql

_ALLOWED = {"SELECT", "INSERT", "UPDATE", "DELETE", "TRUNCATE", "REFERENCES", "TRIGGER"}


def _normalize_privileges(privileges):
    cleaned = []
    for p in privileges:
        up = str(p).strip().upper()
        if up not in _ALLOWED:
            raise ValueError(f"Unsupported privilege: {p}")
        if up not in cleaned:
            cleaned.append(up)
    if not cleaned:
        raise ValueError("At least one privilege is required")
    return cleaned


def grant_postgres_table_privileges(dsn, schema, table, role, privileges, with_grant_option=False):
    privs = _normalize_privileges(privileges)
    query = sql.SQL("GRANT {privs} ON TABLE {tbl} TO {role}").format(
        privs=sql.SQL(", ").join(sql.SQL(p) for p in privs),
        tbl=sql.Identifier(schema, table),
        role=sql.Identifier(role),
    )
    if with_grant_option:
        query = query + sql.SQL(" WITH GRANT OPTION")
    conn = psycopg2.connect(dsn)
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(query)
    finally:
        conn.close()
    return {
        "schema": schema,
        "table": table,
        "role": role,
        "privileges": privs,
        "with_grant_option": bool(with_grant_option),
    }

import subprocess


def run_sql_migration_script(db_url, script_path):
    cmd = ["psql", db_url, "-v", "ON_ERROR_STOP=1", "--single-transaction", "-f", script_path]
    r = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
    return {
        "returncode": r.returncode,
        "stdout": r.stdout[-4000:],
        "stderr": r.stderr[-4000:],
    }

import sqlite3
from dataclasses import dataclass


@dataclass
class ArchiveResult:
    source: str
    destination: str
    rows_moved: int


def move_sqlite_table_rows_to_archive(db_path, table, archive_table, date_column, cutoff):
    for ident in (table, archive_table, date_column):
        if not ident.replace("_", "").isalnum():
            raise ValueError(f"Invalid identifier: {ident}")
    conn = sqlite3.connect(db_path)
    try:
        with conn:
            conn.execute(f'CREATE TABLE IF NOT EXISTS "{archive_table}" AS SELECT * FROM "{table}" WHERE 0')
            conn.execute(
                f'INSERT INTO "{archive_table}" SELECT * FROM "{table}" WHERE "{date_column}" < ?',
                (cutoff,),
            )
            cur = conn.execute(f'DELETE FROM "{table}" WHERE "{date_column}" < ?', (cutoff,))
            moved = cur.rowcount
    finally:
        conn.close()
    return ArchiveResult(source=table, destination=archive_table, rows_moved=moved)
